.tpi-sort-info-cards-wrapper {
    flex-wrap: nowrap !important;
    overflow: auto;
    padding: 0 10px;
    padding-bottom: 20px;
}

.tpi-sort-info-card-item:not(:empty) {
    border-radius: 20px;
    border: 1px solid #e8e8e8;
    padding: 20px;
    box-shadow: 0px 0px 10px 0px #00000014;
    background: #fbfbfb;
    height: fit-content;

    & > div > div > div:first-child span {
        color: #858585;
    }
/* 
    &[data-damaged-card="true"]{
        min-width: 650px;
    } */
}

.tpi-sort-info-card-item:empty{
    display: none;
}

.tpi-sort-info-card-item:has(span[data-i18n-key="pages.sortable-item:main-info.title"]) {
    max-width: 560px !important;
    min-width: 560px !important;
}

.tpi-sort-label-wrapper{
    display: flex;
    align-items: center;
    gap: 10px;
}

icon.tpi-sort-label-icon{
    width: 20px;
    height: 20px;
    padding: 0px;
    display: flex;
    justify-content: center;
    align-items: flex-start;
    
    svg {
        width: 20px !important;
        height: 20px !important;
        color: currentColor;
    }
}

span.tpi-sort-label-title{
    display: flex;
    align-items: center;
    line-height: 1rem;
    font-weight: 500;
}


.tpi-sort-info-card-item-title-wrapper{
    --tpi-sort-card-title-bg-color: #f4f4f4;
    --tpi-sort-card-title-border-color: #e9e8e8;
    --tpi-sort-card-title-outline-width: 4px;
    position: relative;
    width: fit-content;
    display: flex;
    gap: 6px;
    background: var(--tpi-sort-card-title-bg-color);
    box-shadow: 0px 0px 0px var(--tpi-sort-card-title-outline-width) var(--tpi-sort-card-title-bg-color), 0px 0px 0px calc(var(--tpi-sort-card-title-outline-width) + 1px) var(--tpi-sort-card-title-border-color);
    border-radius: 5px;
    padding: 0px 4px;
    align-items: center;

    p.tpi-sort-card-item-title-text{
        margin: 0;
        font-weight: 700;
        font-size: 20px;
    }

    icon.tpi-sort-card-item-title-icon svg{
        width: 18px;
        height: 18px;
        color: currentColor;
    }
}

.tpi-sort-card-custom-data-item-wrapper{
    gap: 16px;
    flex-flow: row;
    display: flex;
}

.tpi-sort-card-custom-data-item-title{
    min-width: 258px;
    align-items: flex-start;
}

.tpi-sort-card-custom-data-item-title,
.tpi-sort-card-custom-data-item-content{
    flex-basis: 33.333333%;
    color: #858585;
    display: flex;
    gap: 10px;
    line-height: 20px;
    &[sheva_r6]{color: red;}

    icon.tpi-sort-card-custom-data-item-icon{
        display: flex;
        align-items: center;
        min-width: 20px;
        min-height: 20px;
    }

    icon.tpi-sort-card-custom-data-item-icon svg{
        width: 20px;
        height: 20px;
        color: currentColor;
    }

    p.tpi-sort-card-custom-data-item-text,
    a.tpi-sort-card-custom-data-item-link{
        margin: 0;
        display: flex;
        align-items: center;
        line-height: 20px;
        font-weight: 500;
        font-size: 16px;
    }
}


a.tpi-sort-card-custom-data-item-link{
    position: relative;
    z-index: 1;
    &:hover{
        color: #fff;
    }
    &::before {
        content: '';
        display: flex;
        position: absolute;
        left: -2px;
        top: 0;
        width: calc(100% + 6px);
        height: 100%;
        background: currentColor;
        z-index: -1;
        border-radius: 8px;
        box-shadow: 0px 0px 0px 4px;
        color: #5d5dff;
        padding: 0px 2px;
        transition: 50ms ease-in-out;
        transform: scale(0);
    }
    &:focus-visible{
        color: #fff;
        outline: none;
    }

    &:hover::before,
    &:focus-visible::before{
        transform: scale(1);
        transition: 200ms cubic-bezier(.17,.73,0,1.32);
    }
}

.tpi-sort-card-custom-data-ticket-wrapper{
    display: flex;
    align-items: center;
    gap: 1ch;
}

.tpi-sort-card-custom-data-ticket-link{
    width: fit-content;
    display: flex;
    align-items: center;
    line-height: 20px;
}

.tpi-sort-card-custom-data-ticket-created-date{
    font-size: .7rem;
    color: #212121;
    display: flex;
    align-items: center;
    line-height: .7rem;
}

.tpi-sort-card-custom-data-item-content{
    color: #212121;
    display: flex;
    flex-wrap: wrap;
    flex-basis: 50.3333%;

    /* &:has(.tpi-sort-card-custom-data-item-link:nth-child(2)) .tpi-sort-card-custom-data-item-link:not(:last-child):not(:has(+ .tpi-sort-card-custom-data-copy))::after {
        content: ',';
        display: inline;
        color: #000;
        pointer-events: none;
    }

    & .tpi-sort-card-custom-data-item-link:not(:last-child):not(:has(+ .tpi-sort-card-custom-data-copy))::after {
        content: ',';
        display: inline;
        color: #000;
        pointer-events: none;
    } */
}

.tpi-sort-card-custom-tickets-wrapper{
    display: flex;
    flex-flow: column;
}

.tpi-sort-card-custom-data-item-loader {
    width: 20px;
    height: 20px;
    border: 2px solid #e0e0e0;
    border-top: 2px solid #0077ff;
    border-radius: 50%;
    animation: tpi-spin 1s linear infinite;
}

@keyframes tpi-spin {
    0% { transform: rotate(0deg); }
    100% { transform: rotate(360deg); }
}

button.tpi-sort-card-custom-data-copy{
    --tpi_copy_button_color: #e8e8e8;
    width: 20px;
    height: 20px;
    background: var(--tpi_copy_button_color);
    border-radius: 4px;
    box-shadow: 0px 0px 0px 4px var(--tpi_copy_button_color);
    transition: 100ms linear;
    margin-left: 2px;

    &:focus-visible,
    &:hover{
        filter: brightness(0.9);
    }

    &:active{
        --tpi_copy_button_color: #fc0;
        transform: scale(.9);
    }

    icon.tpi-sort-card-custom-data-copy-icon{
        width: 100%;
        height: 100%;
        display: flex;
        justify-content: center;
        align-items: center;
        color: #212121;
        padding: 1px;
    }
    icon.tpi-sort-card-custom-data-copy-icon svg{
        fill: currentColor;
        width: 100%;
        height: 100%;
    }
}

