a.tpi-sort-damaged-list-data{
    max-width: 140px;
    text-overflow: ellipsis;
    white-space: pre-wrap;
    display: flex;
    align-items: center;
    gap: .5ch;
    position: relative;
    z-index: 1;
    &:hover{
        color: #fff;
    }
    &::before {
        content: '';
        display: flex;
        position: absolute;
        left: -3px;
        top: 0;
        width: calc(100% + 6px);
        height: 100%;
        background: currentColor;
        z-index: -1;
        border-radius: 8px;
        box-shadow: 0px 0px 0px 4px;
        color: #5d5dff;
        padding: 0px 2px;
        transition: 50ms ease-in-out;
        transform: scale(0);
    }
    &:focus-visible{
        color: #fff;
        outline: none;
    }

    &:hover::before,
    &:focus-visible::before{
        transform: scale(1);
        transition: 200ms cubic-bezier(.17,.73,0,1.32);
    }

    icon.tpi-sort-damaged-list-pdf-icon{
        color: currentColor;
        --iconSize: 16px;
        width: var(--iconSize);
        min-width: var(--iconSize);
        height: var(--iconSize);
