    border-radius: 8px;
    overflow: hidden;
}

.tpi-damaged-photo-item {
    position: relative;
    overflow: hidden;
    cursor: pointer;
    background: #edf2f7;
}

.tpi-damaged-photo-overlay {
    position: absolute;
    top: 0;
    left: 0;
    right: 0;
    bottom: 0;
    background: #00000099;
    display: flex;
    align-items: center;
    justify-content: center;
    color: white;
    font-size: 1.25rem;
    font-weight: 400;
    pointer-events: none;
    text-shadow:0px 0px 4px #000,
                0px 0px 4px #000,
                0px 0px 4px #000;
    font-family: 'Roboto';
}

.tpi-damaged-photo-item img {
    width: 100%;
    height: 100%;
    object-fit: cover;
    display: block;
    transition: transform 0.2s;
}

.tpi-damaged-photo-item img:hover {
    transform: scale(1.02);
}

.tpi-damaged-modal-overlay {
    display: none;
    position: fixed;
    top: 0;
    left: 0;
    width: 100%;
    height: 100%;
    background: rgba(0, 0, 0, 0.92);
    z-index: 9999999;
    justify-content: center;
    align-items: center;
    flex-flow: column;
    padding: 20px;
    opacity: 0;
    transition: opacity 0.3s;
}

.tpi-damaged-modal-overlay.open {
    display: flex;
    opacity: 1;
}

.tpi-damaged-modal-content {
    position: relative;
    width: 100%;
    max-width: 900px;
    max-height: 90dvh;
    display: flex;
    gap: 20px;
    flex-flow: column;
    align-items: center;
}

.tpi-damaged-modal-close {
    position: absolute;
    top: 50px;
    right: 50px;
    background: transparent;
    border: none;
    color: #fff;
    cursor: pointer;
    opacity: .7;
    transition: opacity 200ms;
    z-index: 10;
    &:hover {
        opacity: 1;
    }

    icon{
        width: 30px;
        height: 30px;
        display: flex;
        position: relative;
        justify-content: center;
        align-items: center;
    }

    icon svg{
        width: 100%;
        height: 100%;
        color: currentColor;
    }
}

.tpi-damaged-modal-image-container {
    width: 100%;
    height: 65vh;
    display: flex;
    justify-content: center;
    align-items: center;
    overflow: hidden;
    position: relative;
    background: transparent;
    cursor: default;
    border-radius: 20px;
}

.tpi-damaged-modal-image-container:active {
    cursor: grabbing;
}

.tpi-damaged-modal-image-container img {
    max-width: 100%;
    max-height: 100%;
    object-fit: contain;
    user-select: none;
    -webkit-user-drag: none;
    will-change: transform;
    transition: transform 0.2s ease-out;
    box-shadow: 0px 0px 16px 0px #000;
}

.tpi-damaged-modal-image-container img.no-transition {
    transition: none !important;
}

.tpi-damaged-modal-controls {
    display: flex;
    gap: 20px;
    align-items: center;
    color: #fff;
}

.tpi-damaged-modal-controls button {
    background: rgba(255, 255, 255, 0.15);
    border: none;
    color: #fff;
    font-size: 20px;
    width: 40px;
    height: 40px;
    border-radius: 50%;
    cursor: pointer;
    transition: background 0.2s;
    display: flex;
    align-items: center;
    justify-content: center;
    &:hover {
        background: #ffffff4d;
    }
}

.tpi-damaged-modal-controls .zoom-level {
    font-size: 14px;
    min-width: 50px;
    text-align: center;
}

.tpi-damaged-modal-thumbnails {
    display: flex;
    gap: 8px;
    padding: 4px 0;
    max-width: 100%;
    justify-content: center;
}

.tpi-damaged-modal-thumbnails img {
    width: 80px;
    height: 80px;
    object-fit: cover;
    border-radius: 8px;
    cursor: pointer;
    border: 4px solid transparent;
    transition: border-color 0.2s, transform 0.2s;
    opacity: 0.6;
}

.tpi-damaged-modal-thumbnails img.active {
    border-color: #fc0;
    opacity: 1;
    transform: scale(1.05);
}

.tpi-damaged-modal-thumbnails img:hover {
    opacity: 1;
}

@media (max-width: 560px) {
    .tpi-damaged-modal-image-container {
        height: 50vh;
    }
    .tpi-damaged-modal-thumbnails img {
        width: 40px;
        height: 40px;
    }
